Translate("deDE", "alterac-mountains", {
	title = "Alteracgebirge",
	aliases = { "Alterac", "Königreich Alterac" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Alteracgebirge erhebt sich nördlich des {link:hillsbrad-foothills}Vorgebirges von Hillsbrad{/link}, eine Mauer aus Schnee und grauem Stein zwischen den Ufern des {red:lordamere-lake}Lordameresees{/red} und den toten Landen der Pestländer. Einst war es ein eigenes Königreich. Seine {link:capital-city}Hauptstadt{/link} liegt zerbrochen in den hohen Pässen, und sein Name wird an den Höfen der {link:humans}Menschen{/link} noch immer wie ein Fluch ausgesprochen, denn Alterac verriet die {link:alliance}Allianz{/link} in ihrer dunkelsten Stunde. Heute gehören die Berge dem, der sie halten kann: verbannten Adligen und ihren Halsabschneidern, Ogern, die mit gestohlenen Relikten gekrönt sind, Zauberern, Assassinen, {link:orcs}Orcs{/link} und Zwergen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Alterac war einer der Stadtstaaten, die die {link:humans}Menschen{/link} von {link:arathor}Arathor{/link} nach dem Tod von König {link:thoradin}Thoradin{/link} in der Wildnis gründeten, als ihr Reich über die Mauern von {link:stromgarde-keep}Strom{/link} hinauswuchs. Es gedieh an den Straßen durch die Berge, und mit der Zeit wurde es eines der menschlichen Königreiche, die das alte Reich unter sich aufteilten. Die Familie Perenolde herrschte von einer Burg in der hoch gelegenen Stadt aus. Die Höfe des Oberlands ernährten es, und die Magier von {link:dalaran}Dalaran{/link} waren seine Nachbarn jenseits des Sees.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Das {link:syndicate}Syndikat{/link} hält einen großen Teil des alten Königreichs. Seine Lords haben die Geisterstadt {link:strahnbrad}Strahnbrad{/link} zu ihrer Festung gemacht und das {link:the-uplands}Oberland{/link} zu ihrem Jagdgrund, und {link:lord-aliden-perenolde}Lord Aliden Perenolde{/link} hält Hof in einem Herrenhaus am Seeufer. Fremde in schwarzen Roben stehen an seiner Seite. Die zerstörte {link:capital-city}Hauptstadt{/link} gehört den {link:crushridge-ogres}Crushridge{/link}-Ogern und ihrem Kriegsherrn {link:mug-thol}Mug'thol{/link}, der eine Krone trägt, die {link:sylvanas-windrunner}die Dunkle Fürstin{/link} zurückhaben will. Im Westen steht {link:dalaran}Dalaran{/link} wiederaufgebaut, und seine große Barriere ist gefallen. Im Osten beobachten die Assassinen von {link:ravenholdt-manor}Ravenholdt{/link} das Syndikat aus ihrem verborgenen Anwesen. Am Eingang des Alteractals sammeln {link:dwarves}Zwerge{/link} aus {link:kingdom-of-ironforge}Ironforge{/link} und {link:orcs}Orcs{/link} des Frostwolfklans Soldaten für einen eigenen Krieg. {link:southshore}Southshore{/link} wie {link:tarren-mill}Tarrens Mühle{/link} schicken Jäger in den Schnee, jedes aus eigenen Gründen.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Das {link:syndicate}Syndikat{/link}.{/b} Gefallene Adlige Alteracs, mit den Dieben, Wegelagerern und Schattenmagiern, die ihnen dienen.
• {b}Die {link:crushridge-ogres}Crushridge-Oger{/link}.{/b} Eine Kriegerschar von Ogern, die die zerstörte {link:capital-city}Hauptstadt{/link} genommen und in den Hügeln dahinter einen Hügelbau gegraben hat.
• {b}Die Magier von {link:dalaran}Dalaran{/link}.{/b} Die {link:kirin-tor}Kirin Tor{/link} und ihre Wachen, Arbeiter und gebundenen Elementare.
• {b}Die Assassin's League.{/b} Die Schurken von {link:ravenholdt-manor}Ravenholdt{/link}, die keinem König gehorchen.
• {b}Die {link:stormpike-guard}Stormpikegarde{/link} und der {link:frostwolf-clan}Frostwolfklan{/link}.{/b} {link:dwarves}Zwerge{/link} und {link:orcs}Orcs{/link} im Krieg um das {link:alterac-valley}Alteractal{/link}.
• {b}Tiere.{/b} Yetis in den Höhlen, Berglöwen an den Hängen und Bären in den niederen Hügeln.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Das Königreich.{/b} Jahrhundertelang war Alterac ein kleines, aber stolzes Reich des Nordens, oft im Streit mit seinem Nachbarn {link:stromgarde-keep}Stromgarde{/link}.
• {b}Der Zweite Krieg.{/b} König {link:aiden-perenolde}Aiden Perenolde{/link} zweifelte von Anfang an an der {link:alliance}Allianz{/link}. Als die {link:horde}Horde{/link} seine Berge erreichte, schloss er einen geheimen Pakt mit {link:orgrim-doomhammer}Orgrim Doomhammer{/link} und öffnete die südlichen Pässe. Die {link:orcs}Orcs{/link} überquerten sie in Tagen statt in Monaten und belagerten die {link:capital-city}Hauptstadt{/link} von {link:lordaeron}Lordaeron{/link}.
• {b}Der Fall.{/b} Als der Verrat bekannt wurde, marschierten die Heere der Allianz gegen Alterac. König {link:terenas-menethil}Terenas Menethil{/link} setzte Perenolde ab und hielt ihn in seinem eigenen Palast gefangen. Das Königreich erhob sich nie wieder, und sein Volk zerstreute sich.
• {b}Die Seuche.{/b} Im {link:third-war}Dritten Krieg{/link} fegte die {link:scourge}Geißel{/link} durch Lordaeron, und {link:archimonde}Archimonde{/link} stürzte {link:dalaran}Dalaran{/link} jenseits des Sees. Was an Ordnung in den Bergen geblieben war, starb mit ihnen.]=],
		},
		{
			title = "Überlieferungen der Berge",
			text = [=[• Die Tiara der Perenoldes, ein Erbstück des alten Königshauses, wurde von den Juwelieren Ironforges gefertigt und mit Smaragden besetzt. Sie ging verloren, als Alterac fiel. Ein Ogermagier der {link:crushridge-ogres}Crushridge{/link} soll sie nun bei sich tragen.
• Der Magistrat von {link:southshore}Southshore{/link} wurde von Assassinen ermordet, die nie gefunden wurden. Sein Nachfolger glaubt, dass das {link:syndicate}Syndikat{/link} sie angeheuert hat.
• Jäger sagen, dass ein großer Yeti namens Frostmaw über die Höhen oberhalb der {link:growless-cave}Growlesshöhle{/link} streift.]=],
		},
	},
})

Translate("deDE", "ruins-of-alterac", {
	title = "Die Ruinen von Alterac",
	aliases = { "Stadt Alterac" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Ruinen von Alterac waren einst die {link:capital-city}Hauptstadt{/link} des Königreichs, eine ummauerte Stadt in den hohen Pässen. Hier hielt König {link:aiden-perenolde}Aiden Perenolde{/link} Hof, und hier sagte er seinen Offizieren, dass {link:alterac-mountains}Alterac{/link} sich auf die Seite der {link:horde}Horde{/link} stellen werde. Als die {link:alliance}Allianz{/link} ihn holen kam, floh sein Volk, und die Stadt wurde nie wiederaufgebaut. Heute halten die {link:crushridge-ogres}Crushridge-Oger{/link} die zerbrochenen Straßen. Ihr Kriegsherr {link:mug-thol}Mug'thol{/link} hat sein Lager im alten Palast aufgeschlagen, dem einzigen Gebäude, das noch ganz steht. Die Verlassenen von {link:tarren-mill}Tarrens Mühle{/link} haben geschworen, seinen Kopf über diesen Mauern auf einen Pfahl zu stecken.]=],
		},
	},
})

Translate("deDE", "strahnbrad", {
	title = "Strahnbrad",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Strahnbrad war eine Stadt der östlichen Vorberge, an der Straße zwischen {link:alterac-mountains}Alterac{/link} und den Landen Lordaerons. Am Vorabend des {link:third-war}Dritten Krieges{/link} überfielen {link:orcs}Orcs{/link} sie, um Sklaven zu fangen, und Prinz {link:arthas-menethil}Arthas Menethil{/link} kam zu spät, um viele ihrer Bewohner zu retten. Heute ist sie eine Geisterstadt und die wichtigste Festung des {link:syndicate}Syndikats{/link}. Seine Lords treffen sich in ihren leeren Hallen, und ihre alten Zellen halten ihre Gefangenen. Der Orc {link:gol-dir}Gol'dir{/link} wurde dort als Sklave gehalten, gezwungen, für seine Häscher zu graben und zu schleppen. Der Magistrat von {link:southshore}Southshore{/link} will die Siegelringe der Adligen, die sich unter ihren Dieben verbergen.]=],
		},
	},
})

Translate("deDE", "crushridge-hold", {
	title = "Crushridgehöhle",
	aliases = { "Slaughter Hollow", "Galgeneck" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Crushridgehöhle ist der Ogerhügel, den die {link:crushridge-ogres}Crushridge{/link} in {link:razorfen-downs}die Hügel{/link} nahe der zerstörten {link:capital-city}Hauptstadt{/link} gegraben haben. Ihre Höhlen und Lager wimmeln von Rohlingen, Schlägern und Magiern, und tiefer in den Bergen halten sie einen zweiten Hügel bei Slaughter Hollow. Ihre Patrouillen bewachen die Wegkreuzung von Galgeneck bei einem alten verfallenen Turm. Der Marschall von {link:southshore}Southshore{/link} fürchtet den Tag, an dem die {link:ogres}Oger{/link} sich sicher genug fühlen, um in die Vorberge herabzukommen, und er zahlt gut für jeden Fingerknochen, den seine Jäger zurückbringen.]=],
		},
	},
})

Translate("deDE", "the-uplands", {
	title = "Das Oberland",
	aliases = { "Oberland" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Oberland sind die hohen Hügel des nördlichen {link:alterac-mountains}Alterac{/link}, nördlich von {link:strahnbrad}Strahnbrad{/link}. Es war das Ackerland des alten Königreichs. Heute ist es das Kernland des {link:syndicate}Syndikats{/link}, das hier am stärksten ist. {link:baron-vardus}Baron Vardus{/link} hat seine Lager in diesen Hügeln, und hier warten auch die Schattenmagier des {link:argus-wake}Argus Wake{/link}, die als Verbündete des Syndikats nach Alterac kamen. Der Magistrat von {link:southshore}Southshore{/link} schickt seine Jäger nach Norden ins Oberland, wenn er den Kopf eines Adligen will.]=],
		},
	},
})

Translate("deDE", "dandred-s-fold", {
	title = "Dandreds Senke",
	aliases = { "Nebelufer" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Dandreds Senke ist ein Herrenhaus mit einem kleinen Hafen am Nebelufer, wo das westliche {link:the-uplands}Oberland{/link} auf den {red:lordamere-lake}Lordameresee{/red} trifft. Es ist das Haus von {link:lord-aliden-perenolde}Lord Aliden Perenolde{/link}, der sich Herr dieser Lande nennt. Assassinen und Vollstrecker des Syndikats bewachen seine Türen. Im oberen Stockwerk lebt seine Geliebte {link:elysa}Elysa{/link}, und neben ihm steht {link:nagaz}Nagaz{/link}, der {link:orcs}Orc{/link}, der für den {link:argus-wake}Argus Wake{/link} spricht. Die Krieger von {link:tarren-mill}Tarrens Mühle{/link} kennen den Weg hierher. Die Jäger von {link:southshore}Southshore{/link} ebenso.]=],
		},
	},
})

Translate("deDE", "sofera-s-naze-and-corrahn-s-dagger", {
	title = "Soferas Landspitze und Corrahns Dolch",
	aliases = { "Soferas Landspitze", "Corrahns Dolch" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Soferas Landspitze und Corrahns Dolch sind zwei Hügel, die von den Bergen zu den Vorbergen hinabreichen, nördlich und westlich von {link:tarren-mill}Tarrens Mühle{/link}. Das {link:syndicate}Syndikat{/link} unterhält auf beiden Lager. Von hier ziehen seine Wegelagerer und Diebe hinab, um die Straßen von {link:hillsbrad-foothills}Hillsbrad{/link} auszurauben, und von hier, so glaubt {link:southshore}Southshore{/link}, kamen die Assassinen, die seinen letzten Magistrat töteten. Auf einem Hügel nahe einem dieser Lager liegt ein verwundeter Handlanger des Syndikats namens Valik und feilscht um einen letzten Trunk.]=],
		},
	},
})

Translate("deDE", "growless-cave", {
	title = "Growlesshöhle",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Growlesshöhle öffnet sich in den kalten Höhen des mittleren {link:alterac-mountains}Alterac{/link}. Sie ist ein Bau von Bergyetis, und ein weißer Yeti namens Skhowl wird manchmal nahe ihrem Eingang gesehen. Die Höhle hat auch eine dunklere Geschichte. Der Zauberer {link:helcular}Helcular{/link}, der ein Lich werden wollte, entzündete in ihr einen seiner drei zeremoniellen Scheiterhaufen: die Flamme von Uzel. Sein Lehrling in {link:tarren-mill}Tarrens Mühle{/link} erinnert sich noch an den Weg. Jäger sagen, dass Fleisch, das auf der Flamme verbrannt wird, den großen Yeti Frostmaw von den Gipfeln herablockt.]=],
		},
	},
})

Translate("deDE", "chillwind-point", {
	title = "Chillwindspitze",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Chillwindspitze ist eine Anhöhe am äußersten Ostrand von {link:alterac-mountains}Alterac{/link}, wo ein kalter Wind aus den Pestländern durch eine Klamm weht. Auf ihr stehen die Ruinen einer alten Trollstätte, weit älter als jedes menschliche Königreich hier. Ein Trolleinsiedler, {link:bath-rah-the-windwatcher}Bath'rah der Windbehüter{/link}, hat sein Lager neben dem Fluss darunter aufgeschlagen. Er hat Jahre damit verbracht, diese Ruinen zu beobachten und auf den Tag zu warten, an dem ein Held kommt, um sich dem Windlord zu stellen, der dort haust.]=],
		},
	},
})

Translate("deDE", "ravenholdt-manor", {
	title = "Ravenholdt-Anwesen",
	aliases = { "Ravenholdt" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Ravenholdt-Anwesen verbirgt sich in den östlichen Hügeln, wo {link:alterac-mountains}Alterac{/link} auf {link:hillsbrad-foothills}Hillsbrad{/link} trifft, oberhalb der Ruinen von {link:durnholde-keep}Durnholde{/link}. Keine Straße führt offen dorthin. Es ist das Haus von {link:lord-jorach-ravenholdt}Lord Jorach Ravenholdt{/link} und der Sitz der Assassin's League. Hier werden die besten Diebe und Mörder der nördlichen Lande ausgebildet, beobachtet und geprüft. Fremde sind nicht willkommen. Wer ungeladen kommt, findet selten die Tür, und wer geladen ist, muss erst seine List beweisen, nur um sie zu erreichen. Die Liga liegt seit Jahren im Krieg mit dem {link:syndicate}Syndikat{/link}.]=],
		},
	},
})

Translate("deDE", "lordamere-internment-camp", {
	title = "Lordamere-Internierungslager",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Lordamere-Internierungslager steht auf einem Hügel nahe {link:dalaran}Dalaran{/link}. Nach dem {link:second-war}Zweiten Krieg{/link} war es eines der {link:internment-camps}Internierungslager{/link} Lordaerons, in denen besiegte {link:orcs}Orcs{/link} hinter Mauern gehalten wurden. Die Orcs sind fort. Heute nutzen die {link:the-wizards-of-ambermill}Zauberer von Dalaran{/link} das Lager als ihr eigenes Gefängnis. Vier {link:forsaken}Verlassene{/link}, die Artefakte aus einem Gewölbe von {link:undercity}Undercity{/link} stahlen, flohen hierher, und die Magier fingen sie und stellten sie unter Quarantäne. {link:warden-belamoore}Aufseherin Belamoore{/link} hütet das Lager und untersucht, was die Diebe bei sich trugen. Die Dunkle Fürstin will ihre Artefakte zurück.]=],
		},
	},
})

Translate("deDE", "alterac-valley", {
	title = "Alteractal",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Südlich der hohen Gipfel führt ein Tunnel ins Alteractal, ein Land aus Eis und Kiefern zwischen den Bergen. Der {link:frostwolf-clan}Frostwolfklan{/link} der {link:orcs}Orcs{/link} beansprucht {link:stranglethorn-vale}das Tal{/link} als seine Heimat. Die {link:dwarves}Zwerge{/link} der {link:stormpike-guard}Stormpikegarde{/link} sind gekommen, um dort nach Relikten und Erz zu graben, und sie gedenken, das Land für {link:kingdom-of-ironforge}Ironforge{/link} zu nehmen. Vor dem Tunnel unterhalten beide Heere Lager. Ihre Offiziere empfangen neue Soldaten, prüfen sie und schicken sie ins Tal. Die Kämpfe darin hören nie wirklich auf.]=],
		},
	},
})

Translate("deDE", "old-dalaran-ruins", {
	title = "Old Dalaran Ruins",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Nicht ganz {link:dalaran}Dalaran{/link} erhob sich wieder. Als {link:archimonde}Archimonde{/link} die Stadt im {link:third-war}Dritten Krieg{/link} stürzte, wurden ihre Außenbezirke zusammen mit ihrem Herzen zerbrochen. Die Magier errichteten ihre neue Stadt hinter einer Barriere, doch die Ruinen der alten liegen noch an den Ufern des {red:lordamere-lake}Lordameresees{/red}. Ihre Zauberer und gebundenen Elementare patrouillierten einst durch sie, und Gelehrte der Verlassenen glauben, dass noch magische Schätze zwischen den Steinen liegen. Seit die Barriere fort ist, stehen die Ruinen jedem offen, der kühn genug ist, sie zu durchsuchen.]=],
		},
	},
})

Translate("deDE", "lord-jorach-ravenholdt", {
	title = "Lord Jorach Ravenholdt",
	subtitle = "Lord der Assassin's League",
	found = "Im Ravenholdt-Anwesen",
	hint = [=[Findet den Herrn des verborgenen Anwesens in den östlichen Hügeln, falls seine Diener Euch einlassen.]=],
	allegiance = "Assassin's League · Ravenholdt",
	aliases = { "Jorach Ravenholdt", "Meister Ravenholdt" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Lord Jorach Ravenholdt ist der Herr des {link:ravenholdt-manor}Ravenholdt{/link}-Anwesens und der Lord der Assassin's League. Seine Schurken sind die geschicktesten der nördlichen Lande, und sie dienen keinem König. Er ist gnädig zu seinen Gästen, großzügig zu denen, die ihm gut dienen, und sehr verschwiegen über seine eigenen Angelegenheiten. Er sagt nicht, was er will. Er bittet einfach und wartet ab, wer klug genug ist, es zu tun.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Jorachs Liga ist der älteste Feind, den das {link:syndicate}Syndikat{/link} in {link:alterac-mountains}Alterac{/link} hat. Seine Agenten versuchen nicht, die Mitglieder des Syndikats einzeln zu töten, denn es sind zu viele. Sie stehlen ihre Abzeichen, und um die Beschämten kümmern sich dann ihre eigenen Leute. Es ist ein stillerer Krieg als der, den {link:southshore}Southshore{/link} führt, und vielleicht ein wirksamerer.]=],
		},
		{
			title = "Taten",
			text = [=[• Er herrscht über das {link:ravenholdt-manor}Ravenholdt-Anwesen{/link} und die Schurken, die dort ausgebildet werden.
• Er führt einen langen Krieg aus Diebstahl und Furcht gegen das {link:syndicate}Syndikat{/link}.
• Er ruft vertrauenswürdige Schurken herbei, um zurückzuholen, was ihm lieb ist, und er belohnt sie reich.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Wenig ist über Jorachs Leben vor der Liga geschrieben, oder darüber, wie sein Haus in den Besitz dieser Hügel kam. Dieser Eintrag verzeichnet nur, was seine Taten verraten.]=],
		},
	},
	chapters = {
		{
			title = "Eine einfache Bitte",
			hint = "Folgt dem Ruf des Lords von Ravenholdt.",
			text = [=[Der Ruf kam im Geheimen, und Jorach empfing seinen Gast herzlich. Er hatte etwas Kleines verloren: einen blauen Beutel. Die Diebe, die ihn nahmen, waren bereits tot. Sie hatten ihn nicht öffnen können und ihn an die {link:timbermaw-furbolgs}Holzschlund{/link} in {link:azshara}Azshara{/link} verkauft, die ihn für ein heiliges Relikt hielten. Jorach wollte ihn zurück, wenn möglich mit Feingefühl.]=],
		},
		{
			title = "Der azurblaue Schlüssel",
			hint = "Bringt den Schlüssel zum verlorenen Beutel zurück.",
			text = [=[Der Beutel war durch einen Zauber versiegelt, und sein Schlüssel lag bei einem grünen Drachen im versunkenen Tempel der {link:swamp-of-sorrows}Sümpfe des Elends{/link}. Als der Schlüssel zurückgebracht wurde, öffnete Jorach den Beutel. Ein goldenes Licht ergoss sich über ihn, und seine Augen weiteten sich. Was er darin sah, sagte er nicht.]=],
		},
	},
	mentions = {
		{
			text = [=[Das Anwesen {link:ravenholdt-manor}Ravenholdt{/link}, die in seinem Namen gesandte Einladung]=],
		},
		{ text = "Abzeichen des Syndikats" },
		{ text = "Eine einfache Bitte" },
		{ text = "Versiegelter azurblauer Beutel" },
		{ text = "Der azurblaue Schlüssel" },
	},
	bonds = {
		{ id = "fahrad", name = "Fahrad", note = "sein Großmeister der Schurken" },
		{ id = "lord-aliden-perenolde", name = "Lord Aliden Perenolde", note = "der Lord seiner Feinde" },
	},
})

Translate("deDE", "fahrad", {
	title = "Fahrad",
	subtitle = "Großmeister der Schurken",
	found = "Ravenholdt-Anwesen",
	hint = [=[Sucht den Meisterschurken, der die Einladungen nach Ravenholdt schreibt.]=],
	allegiance = "Assassin's League · Ravenholdt",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Fahrad ist der Großmeister der Schurken von {link:ravenholdt-manor}Ravenholdt{/link}. Er ist es, der die jungen Diebe der Welt beobachtet und entscheidet, welche von ihnen es wert sind, unterrichtet zu werden. Seine Briefe finden sie, wo immer sie sind, versiegelt mit dem Zeichen des Anwesens. Wer kommt, muss zuerst eine Prüfung der List auf dem Weg überstehen. Fahrad begrüßt die Überlebenden mit einem Lachen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Fahrad ist die Tür zur Assassin's League. Niemand tritt ihr bei, ohne durch seine Hände zu gehen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er lädt vielversprechende Diebe nach {link:ravenholdt-manor}Ravenholdt{/link} ein und prüft sie auf dem Weg.
• Er kauft die Schließkassetten, die seine Schurken im Feld öffnen.]=],
