Translate("deDE", "aiden-perenolde", {
	title = "Aiden Perenolde",
	subtitle = "Der Verräterkönig von Alterac",
	hint = [=[Erfahrt die Geschichte des Königs, der seine Berge an die Horde verkaufte.]=],
	allegiance = "Königreich Alterac",
	aliases = { "König Perenolde", "Lord Aiden Perenolde" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Aiden Perenolde war der letzte König von {link:alterac-mountains}Alterac{/link}. Er war ein leise sprechender, gebildeter Mann, der ein feines Schwert besaß und es nie benutzte. Seine Rivalen in der {link:alliance}Allianz{/link} hielten ihn für einen Feigling. Er hielt sich für den einzigen König, der weise genug war, zu erkennen, dass die {link:horde}Horde{/link} nicht zu schlagen war. Im {link:second-war}Zweiten Krieg{/link} verriet er die Allianz, um sein eigenes Reich zu retten, und verlor es dabei.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Perenoldes Verrat ist der Grund, warum {link:alterac-mountains}Alterac{/link} in Trümmern liegt. Seine Erben träumen noch immer von der Krone, die er verwirkte, und das {link:syndicate}Syndikat{/link}, das sie führen, ist sein bitteres Erbe.]=],
		},
		{
			title = "Taten",
			text = [=[• Er trat dem Bündnis von {link:lordaeron}Lordaeron{/link} nur widerwillig bei und zweifelte von Anfang an daran.
• Er verbarrikadierte die Pässe seiner Berge, schloss dann einen geheimen Pakt mit {link:orgrim-doomhammer}Orgrim Doomhammer{/link} und öffnete sie.
• Er ermordete den Boten, der Lothars Ruf nach Truppen brachte, und versteckte die Leiche in seiner Burg.
• Er wurde von {link:terenas-menethil}König Terenas{/link} abgesetzt und in seinem Palast in der zerstörten {link:capital-city}Hauptstadt{/link} festgehalten.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik verzeichnet, wann oder wie Aiden Perenolde starb. In der Gefangenschaft soll ihn sein Verstand verlassen haben. Seine Familie wurde unter Bewachung gehalten, und sein ältester Sohn {link:lord-aliden-perenolde}Aliden{/link} versuchte vergeblich, ihren Namen reinzuwaschen.]=],
		},
	},
	chapters = {
		{
			title = "Die offenen Pässe",
			hint = "Erfahrt, warum die Horde Alterac so schnell durchquerte.",
			text = [=[Als die {link:horde}Horde{/link} zu den Bergen kam, schickte Perenolde einen Vogel zu ihrem Kriegshäuptling und traf ihn bei Nacht. Er fand den {link:orcs}Orc{/link} gebildet und ehrenhaft. Sie schlossen einen Vertrag: Die Horde würde unbehelligt hindurchziehen, und {link:alterac-mountains}Alterac{/link} würde verschont. Perenolde zog seine Soldaten nach Norden ab und ließ die südlichen Pässe leer. Eine Überquerung, die Monate hätte dauern sollen, dauerte zwei Tage. Erst als {link:thoras-trollbane}Thoras Trollbane{/link} von {link:stromgarde-keep}Stromgarde{/link} nach Alterac kam und Perenoldes eigenen General gegen ihn wandte, wurden die Pässe wieder geschlossen.]=],
		},
		{
			title = "Das verlorene Erbstück",
			hint = "Holt die Tiara des Königshauses von Alterac zurück.",
			text = [=[Als {link:alterac-mountains}Alterac{/link} fiel, ging die Tiara der Perenoldes verloren. Zwergische Juweliere hatten sie gefertigt, und ihre Smaragde waren die besten, die sie hatten. Sammler in {link:stormwind-city}Stormwind{/link} wollen sie noch immer. Schließlich tauchte sie in den Händen eines Ogermagiers auf, der in den Ruinen genau der Stadt nach Schätzen sucht, in der der König sie einst trug.]=],
		},
	},
	mentions = {
		{ text = "Die Tiara der Perenoldes" },
		{ text = "Edle Tode, gegen die Adligen seines gefallenen Hofes" },
	},
	bonds = {
		{ id = "lord-aliden-perenolde", name = "Lord Aliden Perenolde", note = "sein ältester Sohn" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "sein geheimer Verbündeter" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "der König, der ihn absetzte" },
		{ id = "grel-borg-the-miser", name = "Grel'borg der Geizhals", note = "hält die Tiara seiner Familie" },
	},
})

Translate("deDE", "lord-aliden-perenolde", {
	title = "Lord Aliden Perenolde",
	subtitle = "Lord des Syndikats",
	found = "Dandreds Senke, am Ufer des Lordameresees",
	hint = [=[Sucht den Lord des Syndikats in seinem Herrenhaus am Seeufer.]=],
	allegiance = "Syndikat · Haus Perenolde",
	aliases = { "Aliden Perenolde", "Aliden" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Lord Aliden Perenolde ist der älteste Sohn des Verräterkönigs von {link:alterac-mountains}Alterac{/link} und der Anführer des {link:syndicate}Syndikats{/link}. Er nennt sich Herr der Berge, die sein Vater verlor. Von seinem Herrenhaus in {link:dandred-s-fold}Dandreds Senke{/link} aus lenkt er Diebe, Assassinen und gefallene Adlige in ganz Alterac und {link:hillsbrad-foothills}Hillsbrad{/link}. Er verbirgt seinen Ehrgeiz nicht. Er will das Land zurückerobern und die {link:orcs}Orcs{/link}, die sich ihm entgegenstellen, zu Sklaven machen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Aliden ist der Erbe der Schande Alteracs. Einst versuchte er, den Namen seines Hauses reinzuwaschen. Nun ist er geworden, was seine Feinde immer von ihm sagten.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führt das {link:syndicate}Syndikat{/link} von {link:dandred-s-fold}Dandreds Senke{/link} aus, mit dem {link:argus-wake}Argus Wake{/link} an seiner Seite.
• Er hält Gefangene der {link:horde}Horde{/link} als Sklaven in den {link:camping}Lagern{/link} Alteracs.
• Er hält eine junge Frau namens {link:elysa}Elysa{/link} als Geliebte und schenkte ihr einen Anhänger, der aus {link:durnholde-keep}Durnholde{/link} stammt.]=],
		},
	},
	chapters = {
		{
			title = "Blackmoores Vermächtnis",
			hint = [=[Befreit den Orc, den das Syndikat gefangen hält, und hört, was er erfahren hat.]=],
			text = [=[Aliden kam persönlich, um seinen Gefangenen {link:gol-dir}Gol'dir{/link} zu sehen. Er prahlte vor dem {link:orcs}Orc{/link} mit seinen Plänen: Die Orcs, die ihm trotzten, würden zu Sklaven gemacht, so wie es sein Vater und sein alter Lehrmeister, {link:aedelas-blackmoore}Aedelas Blackmoore{/link}, einst beabsichtigt hatten. Neben ihm stand {link:elysa}Elysa{/link}. Um ihren Hals hing ein Anhänger, den Gol'dir sofort erkannte, denn es war der, den zu finden sein Kriegshäuptling ihn ausgesandt hatte.]=],
		},
		{
			title = "Tarethas Geschenk",
			hint = "Tragt die Antwort der Orcs zum Herrenhaus am Seeufer.",
			text = [=[Die {link:orcs}Orcs{/link} von {link:tarren-mill}Tarrens Mühle{/link} beantworteten seine Prahlerei mit Stahl. Sie kamen nach {link:dandred-s-fold}Dandreds Senke{/link} und erschlugen den Lord des Syndikats in seinem eigenen Haus. {link:elysa}Elysa{/link} flehte um ihr Leben und gab den Anhänger sofort heraus. Sie wolle keine Erinnerung an ihn, sagte sie.]=],
		},
	},
	mentions = {
		{ text = "Blackmoores Vermächtnis" },
		{ text = "Lord Aliden Perenolde" },
		{ text = "Tarethas Geschenk" },
	},
	bonds = {
		{ id = "aiden-perenolde", name = "Aiden Perenolde", note = "sein Vater" },
		{ id = "elysa", name = "Elysa", note = "seine Geliebte" },
		{ id = "nagaz", name = "Nagaz", note = "der Gesandte an seiner Seite" },
		{ id = "aedelas-blackmoore", name = "Aedelas Blackmoore", note = "sein Lehrmeister" },
		{ id = "gol-dir", name = "Gol'dir", note = "sein Gefangener" },
		{ id = "lord-jorach-ravenholdt", name = "Lord Jorach Ravenholdt", note = "sein Feind" },
	},
})

Translate("deDE", "elysa", {
	title = "Elysa",
	subtitle = "Geliebte von Dandreds Senke",
	found = "Das obere Stockwerk des Herrenhauses in Dandreds Senke",
