		},
		{
			title = "Bedeutung",
			text = [=[Ohne es zu wissen, trug Elysa das Schmuckstück, das die {link:horde}Horde{/link} an Perenoldes Tür führte.]=],
		},
		{ title = "Taten", text = "• Sie gibt Tarethas Anhänger her, um ihr Leben zu retten." },
	},
	mentions = {
		{ text = "{link:lord-aliden-perenolde}Lord Aliden Perenolde{/link}" },
		{ text = "Tarethas Geschenk" },
	},
	bonds = {
		{ id = "lord-aliden-perenolde", name = "Lord Aliden Perenolde", note = "ihr Häscher" },
		{ id = "taretha-foxton", name = "Taretha Foxton", note = "trug den Anhänger vor ihr" },
	},
})

Translate("deDE", "nagaz", {
	title = "Nagaz",
	subtitle = "Hierophant des Argus Wake",
	found = "Dandreds Senke, neben Lord Perenolde",
	hint = "Findet den Orc, der neben dem Lord des Syndikats steht.",
	allegiance = "Argus Wake",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Nagaz ist ein {link:orcs}Orc{/link}, der dem {link:argus-wake}Argus Wake{/link} dient und sich als dessen Hierophant unterzeichnet. Er hat sich zum engsten Verbündeten des Syndikats gemacht. In einem Brief in einer geheimen Chiffre schrieb er seinem Herrn, dass die Adligen Alteracs einen Handel eingegangen seien, den sie bereuen würden. Das {link:syndicate}Syndikat{/link} würde seine Berge zurückgewinnen, dann {link:stromgarde-keep}Stromgarde{/link} nehmen, und der Wake würde beide nutzen, um der {link:burning-legion}Brennenden Legion{/link} den Weg zu bereiten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Nagaz enthüllt, dass das {link:syndicate}Syndikat{/link} nicht sein eigener Herr ist. Er ist die Hand einer weit dunkleren Macht in {link:alterac-mountains}Alterac{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er lenkt das {link:syndicate}Syndikat{/link} in Richtung {link:stromgarde-keep}Stromgarde{/link} und {link:arathi-highlands}Arathihochland{/link}.
• Er befehligt die Argus-Schattenmagier des Oberlands.
• Er schrieb den verschlüsselten Brief, den der Prospektor aus {link:ironforge}Ironforge{/link} entschlüsselte.]=],
		},
	},
	mentions = {
		{ text = "Weitere Rätsel" },
		{ text = "Dunkler Rat" },
		{ text = "Das verzauberte Pergament" },
	},
	bonds = {
		{ id = "lord-aliden-perenolde", name = "Lord Aliden Perenolde", note = "sein „Verbündeter“" },
		{ id = "prospector-stormpike", name = "Prospektor Stormpike", note = "las seinen Brief" },
	},
})

Translate("deDE", "baron-vardus", {
