})

Translate("deDE", "mug-thol", {
	title = "Mug'thol",
	subtitle = "Kriegsherr der Crushridge",
	found = "Der alte Palast in den Ruinen von Alterac",
	hint = [=[Stellt Euch dem Ogerkriegsherrn, der in den Ruinen von Alterac eine gestohlene Krone trägt.]=],
