			title = "Taten",
			text = [=[• Er nahm die Krone des Willens für sich und befreite seine Kriegerschar aus dem Dienst der Dunklen Fürstin.
• Er hält die zerstörte {link:capital-city}Hauptstadt{/link} mit seinen Leutnants Targ, Muckrake und Glommus.]=],
		},
	},
	mentions = {
		{ text = "Die Krone des Willens" },
		{ text = "Die Krone des Willens" },
		{ text = "Die Krone des Willens" },
	},
	bonds = {
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "die Herrin, der er entkam" },
		{ id = "melisara", name = "Melisara", note = "will seinen Kopf" },
