})

Translate("deDE", "grel-borg-the-miser", {
	title = "Grel'borg der Geizhals",
	subtitle = "Ogermagier der Crushridge",
	found = "Die Ruinen von Alterac",
	hint = [=[Sucht den gierigen Ogermagier, der in den Ruinen von Alterac nach Schätzen jagt.]=],
	allegiance = "Crushridge-Oger",
	aliases = { "Grel'borg" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Grel'borg der Geizhals ist ein Ogermagier im Dienst von {link:mug-thol}Mug'thol{/link}. Sein Name passt zu ihm. Er wandert durch die Ruinen von {link:alterac-mountains}Alterac{/link} auf der Suche nach Schätzen, und man sagt, er habe den schönsten von allen gefunden: die Tiara der Perenoldes, das verlorene Erbstück der Könige von Alterac. Er lässt Feuer auf jene herabregnen, die kommen, um zu nehmen, was er gefunden hat.]=],
