		{ id = "aiden-perenolde", name = "Aiden Perenolde", note = "der König, dessen Tiara er verwahrt" },
	},
})

Translate("deDE", "bath-rah-the-windwatcher", {
	title = "Bath'rah der Windbehüter",
	subtitle = "Einsiedler der Chillwindspitze",
	found = "Sein Lager am Fluss unterhalb der Chillwindspitze",
	hint = [=[Findet den Trolleinsiedler, der am Fluss unterhalb der Chillwindspitze lagert.]=],
	allegiance = "Keine",
	aliases = { "Bath'rah", "Windbehüter" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Bath'rah ist ein Trolleinsiedler, ein Schamane und ein Waffenschmied. Er hat eine Ewigkeit neben den Ruinen der {link:chillwind-point}Chillwindspitze{/link} verbracht und gewacht. Ein großer Lord des Windes namens Cyclonian haust dort, und Bath'rah wartet auf einen Helden, der stark genug ist, ihn zu besiegen. Aus dem Wirbelwindherzen des gefallenen Elementars, sagt er, könnte er eine Waffe von großer Macht schmieden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Bath'rah ist einer der wenigen, die in diesen nördlichen Hügeln noch die alten Wege der {link:elements}Elemente{/link} kennen. Krieger wie Schamanen suchen ihn auf.]=],
		},
		{
			title = "Taten",
			text = [=[• Er wacht über die Ruinen, in denen Cyclonian haust.
• Er ruft den Windlord für jene herbei, die sich bewähren.
• Er schmiedet Waffen und lehrt die Beherrschung der {link:elements}Elemente{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Der Windlord",
			hint = [=[Sammelt, was der Einsiedler braucht, und stellt Euch dem Windlord.]=],
			text = [=[Das Ritual erforderte viele seltsame Dinge, und jene, die sie sammelten, hatten Stärke wie List bewiesen. Dann rief Bath'rah, und Cyclonian kam. Als der Windlord fiel, wurde sein Wirbelwindherz zum Lager des Einsiedlers zurückgetragen. Es war der Tag, auf den er eine Ewigkeit gewartet hatte.]=],
		},
	},
	mentions = {
		{ text = "Der Windbehüter" },
		{ text = "Cyclonian" },
		{ text = "Die Beschwörung" },
		{ text = "Wirbelwindwaffe" },
		{ text = "Elementarbeherrschung" },
	},
})

Translate("deDE", "warden-belamoore", {
	title = "Aufseherin Belamoore",
	subtitle = "Aufseherin des Lordamere-Lagers",
	found = "Lordamere-Internierungslager",
	hint = [=[Sucht die Zauberin, die das Internierungslager nahe Dalaran hütet.]=],
	allegiance = "Kirin Tor",
	aliases = { "Belamoore" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Aufseherin Belamoore ist die Zauberin von {link:dalaran}Dalaran{/link}, die das {link:lordamere-internment-camp}Lordamere-Internierungslager{/link} hütet. Die vier Verlassenen, die aus {link:undercity}Undercity{/link} flohen, sind nun ihre Gefangenen, und ebenso die vier Artefakte, die sie stahlen. Sie untersucht diese Steine, und sie hat nicht die Absicht, sie der Dunklen Fürstin zurückzugeben.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Belamoore hält, was die Verlassenen in {link:alterac-mountains}Alterac{/link} am meisten wollen. Durch sie ist der Streit zwischen den {link:kirin-tor}Kirin Tor{/link} und {link:undercity}Undercity{/link} zu einer Sache des Blutes geworden.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie hält die Diebe der Verlassenen im Lager fest.
• Sie untersucht die vier Blutsteinartefakte, die sie bei sich trugen.]=],
		},
	},
	mentions = {
		{ text = "Einbruch ins Gefängnis" },
	},
	bonds = {
		{ id = "kegan-darkmar", name = "Kegan Darkmar", note = "ihr Gefangener" },
		{ id = "magus-wordeen-voidglare", name = "Magus Wordeen Voidglare", note = "will, was sie verwahrt" },
	},
})

Translate("deDE", "kegan-darkmar", {
	title = "Kegan Darkmar",
	subtitle = "Deserteur von Undercity",
	found = "Lordamere-Internierungslager",
	hint = [=[Findet den Deserteur der Verlassenen, der im Lager nahe Dalaran festgehalten wird.]=],
	allegiance = "Keine (Deserteur der Verlassenen)",
	aliases = { "Kegan" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kegan Darkmar ist einer von vier {link:forsaken}Verlassenen{/link}, die {link:undercity}Undercity{/link} den Rücken kehrten. Sie brachen in ein gesichertes Gewölbe der Dunklen Fürstin ein, stahlen vier Artefakte, die ihre Apotheker brauchten, und flohen nach {link:dalaran}Dalaran{/link}. Die Zauberer hießen sie nicht willkommen. Sie stellten die vier im {link:lordamere-internment-camp}Lordamere-Internierungslager{/link} unter Quarantäne. Kegan und seine Gefährten Ricter, Alina und Dermot warten nun dort, zwischen den Magiern, die sie festhalten, und den Verlassenen, die sie jagen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Kegans Flucht zeigt, dass nicht alle Verlassenen zufrieden damit sind, der Dunklen Fürstin zu dienen.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik verzeichnet, warum die vier flohen oder was sie in {link:dalaran}Dalaran{/link} zu finden hofften.]=],
		},
	},
	mentions = {
		{ text = "Einbruch ins Gefängnis" },
	},
	bonds = {
		{ id = "warden-belamoore", name = "Aufseherin Belamoore", note = "seine Kerkermeisterin" },
		{ id = "magus-wordeen-voidglare", name = "Magus Wordeen Voidglare", note = "jagt ihn" },
	},
})

Translate("deDE", "prospector-stonehewer", {
	title = "Prospektorin Stonehewer",
	subtitle = "Forscherin der Stormpike-Expedition",
	found = "Das Lager der Stormpike vor dem Alteractal",
	hint = [=[Sprecht mit der zwergischen Prospektorin im Lager der Allianz vor dem Alteractal.]=],
	allegiance = "Stormpikegarde · Forscherliga",
	aliases = { "Stonehewer" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Prospektorin Stonehewer dient der {link:explorers-league}Forscherliga{/link} bei der {link:stormpike-guard}Stormpike-Expedition{/link}. Die Liga glaubt, dass das {link:alterac-valley}Alteractal{/link} Artefakte der Vergangenheit birgt, doch die {link:frostwolf-clan}Frostwolf-Orcs{/link} lassen die {link:dwarves}Zwerge{/link} nicht danach suchen. Stonehewers Antwort ist einfach. Wenn die {link:orcs}Orcs{/link} ihren General verlieren, haben die Forscher Raum zum Graben.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Stonehewer spricht für die gelehrte Seite der Sache der {link:stormpike-guard}Stormpike{/link}: die Suche nach Relikten, die die {link:dwarves}Zwerge{/link}, wie sie sagen, ins Tal zog.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie schickt Soldaten ins Tal gegen {link:drek-thar}Drek'Thar{/link}.
• Sie ehrt die größten Helden der {link:stormpike-guard}Stormpike{/link}.]=],
		},
	},
	mentions = {
		{ text = "Die Schlacht von {link:alterac-mountains}Alterac{/link}" },
		{ text = "Held der {link:stormpike-guard}Stormpike{/link}" },
	},
	bonds = {
		{ id = "drek-thar", name = "Drek'Thar", note = "der General, dessen Niederlage sie will" },
		{ id = "vanndar-stormpike", name = "Vanndar Stormpike", note = "ihr General" },
	},
})

Translate("deDE", "voggah-deathgrip", {
	title = "Voggah Deathgrip",
	subtitle = "Soldat der Frostwolf",
	found = "Das Lager der Frostwolf vor dem Alteractal",
	hint = [=[Sprecht mit dem Orc, der im Lager der Horde vor dem Alteractal Krieger sammelt.]=],
	allegiance = "Frostwolfklan · Horde",
	aliases = { "Voggah" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Voggah Deathgrip wartet im Lager der {link:horde}Horde{/link} vor dem {link:alterac-valley}Alteractal{/link}. Für ihn sind die {link:dwarves}Zwerge{/link} der {link:stormpike-guard}Stormpike{/link} Eindringlinge, nichts weiter. Sie sind mit ihren Verbündeten ins Tal gekommen, und sie müssen vertrieben werden. Der Weg zum Sieg, sagt er, sei, ihren General in seiner Festung im Norden niederzustrecken.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Voggah spricht den schlichten Zorn der {link:frostwolf-clan}Frostwölfe{/link} aus, in deren Heimat die {link:dwarves}Zwerge{/link} ungeladen eingedrungen sind.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt Krieger ins Tal gegen {link:vanndar-stormpike}Vanndar Stormpike{/link}.
• Er ehrt die größten Helden der Frostwolf.]=],
		},
	},
	mentions = {
		{ text = "Die Schlacht um {link:alterac-mountains}Alterac{/link}" },
		{ text = "Held der Frostwolf" },
	},
	bonds = {
		{ id = "vanndar-stormpike", name = "Vanndar Stormpike", note = "der General, dessen Niederlage er will" },
		{ id = "drek-thar", name = "Drek'Thar", note = "sein Häuptling" },
	},
})

Translate("deDE", "vanndar-stormpike", {
	title = "Vanndar Stormpike",
	subtitle = "General der Stormpikegarde",
	found = "Dun Baldar, im Norden des Alteractals",
	hint = [=[Sucht den zwergischen General in seiner Festung am Nordende des Alteractals.]=],
	allegiance = "Stormpikegarde · Königreich Ironforge",
	aliases = { "Vanndar" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Vanndar Stormpike ist der General der {link:stormpike-guard}Stormpikegarde{/link}, der zwergischen Expedition, die ins {link:alterac-valley}Alteractal{/link} gekommen ist. Von seiner Festung Dun Baldar im Norden des Tals aus befehligt er {link:dwarves}Zwerge{/link} und ihre Verbündeten aus jedem Volk der {link:alliance}Allianz{/link}. Er ist ein Bergkönig von wenigen Worten und festem Vorsatz. Das Tal, verspricht er, wird ihnen gehören.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Vanndar ist der Speer von {link:kingdom-of-ironforge}Ironforge{/link} im Norden. Seine Expedition kam, so heißt es, um nach Erz und nach den Relikten der Vergangenheit zu graben. Sein König hat ihr eine härtere Aufgabe gegeben: die Täler von {link:alterac-mountains}Alterac{/link} zu nehmen und für {link:ironforge}Ironforge{/link} zu halten. Diese Aufgabe hat ihn in einen Krieg mit dem {link:frostwolf-clan}Frostwolfklan{/link} gestürzt, dessen Heimat {link:stranglethorn-vale}das Tal{/link} ist, seit die Frostwölfe dorthin verbannt wurden.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führt die {link:stormpike-guard}Stormpikegarde{/link} von Dun Baldar aus.
• Er führt Krieg gegen den {link:frostwolf-clan}Frostwolfklan{/link} und gegen die Winterax-{link:trolls}Trolle{/link} des Tals.
• Er empfängt die Soldaten, die die {link:alliance}Allianz{/link} ins Tal schickt.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Wenig ist über Vanndar vor der Expedition geschrieben, oder über seine Verwandtschaft mit anderen Zwergen, die den Namen {link:stormpike-guard}Stormpike{/link} tragen.]=],
		},
	},
	chapters = {
		{
			title = "Das souveräne Gebot",
			hint = "Folgt dem Ruf Ironforges in die Täler von Alterac.",
			text = [=[Der Ruf erging im Namen von König {link:magni-bronzebeard}Magni Bronzebeard{/link}. Die {link:stormpike-guard}Stormpike{/link} kämpften auf der einen Seite gegen {link:trolls}Trolle{/link} und auf der anderen gegen {link:orcs}Orcs{/link}, und sie brauchten Soldaten. Die Einnahme dieses Landes, erklärten die {link:dwarves}Zwerge{/link}, sei das Recht und die Pflicht Ironforges. Neuen Rekruten wurde gesagt, sie sollten Leutnant Haggerdin vor dem Tal aufsuchen und ihren Dienst bei den Stormpike antreten.]=],
		},
		{
			title = "Die Schlacht um Alterac",
			hint = "Stellt Euch dem General in Dun Baldar.",
			text = [=[Die {link:frostwolf-clan}Frostwölfe{/link} sehen die Sache anders. Für sie sind die {link:stormpike-guard}Stormpike{/link} Eindringlinge. Ihre Krieger wollen sich durch {link:stranglethorn-vale}das Tal{/link} nach Norden bis Dun Baldar kämpfen und den General in seiner eigenen Festung niederstrecken.]=],
		},
	},
	mentions = {
		{ text = "Das souveräne Gebot" },
		{ text = "Die Schlacht um {link:alterac-mountains}Alterac{/link}" },
		{ text = "Bewährungsprobe" },
	},
	bonds = {
		{ id = "drek-thar", name = "Drek'Thar", note = "sein Feind" },
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "sein König" },
		{ id = "prospector-stonehewer", name = "Prospektorin Stonehewer", note = "sucht Relikte für die Expedition" },
	},
})

Translate("deDE", "drek-thar", {
	title = "Drek'Thar",
	subtitle = "Ältester Schamane des Frostwolfklans",
	found = "Burg Frostwolf, im Süden des Alteractals",
	hint = [=[Sucht den alten Schamanen, der von Burg Frostwolf am Südende des Alteractals herrscht.]=],
	allegiance = "Frostwolfklan · Horde",
	aliases = { "Drek'thar" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Drek'Thar ist der älteste Schamane des {link:frostwolf-clan}Frostwolfklans{/link} und der General seiner Krieger im {link:alterac-valley}Alteractal{/link}. Er ist blind, und er ist alt. Er war ein Schamane der Frostwölfe auf Draenor, und er folgte seinem Volk in die Verbannung in diese Berge. Vor langer Zeit nahm er einen jungen {link:orcs}Orc{/link} namens {link:thrall}Thrall{/link} in seine Obhut und lehrte ihn, mit den Geistern zu sprechen. Nun führt er die Frostwölfe von ihrer Burg im Süden des Tals aus.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Drek'Thar ist der Lehrer des Kriegshäuptlings. Durch ihn kehrten die alten Wege der Schamanen zu den {link:orcs}Orcs{/link} zurück, und durch {link:thrall}Thrall{/link} kehrten sie zur ganzen {link:horde}Horde{/link} zurück.]=],
		},
		{
			title = "Taten",
			text = [=[• Er hielt die {link:frostwolf-clan}Frostwölfe{/link} in ihrer Verbannung in {link:alterac-mountains}Alterac{/link} am Leben.
• Er lehrte {link:thrall}Thrall{/link} den Pfad des Schamanen und enthüllte ihm, wer seine Eltern waren.
• Er führt die Verteidigung des Alteractals gegen die {link:stormpike-guard}Stormpikegarde{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Der Sohn Durotans",
			hint = "Erfahrt, wie der Kriegshäuptling zu den Frostwölfen kam.",
			text = [=[Als ein junger, von {link:humans}Menschen{/link} aufgezogener {link:orcs}Orc{/link} ins Lager der {link:frostwolf-clan}Frostwölfe{/link} kam, trug er eine zerrissene Decke aus seiner frühesten Kindheit bei sich. Drek'Thar kannte ihre Zeichen. Der Fremde war der Sohn Durotans, des Häuptlings, der den Clan in die Verbannung geführt hatte und der mit seiner Gefährtin ermordet worden war. Der alte Schamane prüfte den Stolz und die Demut des jungen Orcs und lehrte ihn dann die Wege der Geister.]=],
		},
		{
			title = "Zur Verteidigung der Frostwolf",
			hint = "Steht den Frostwölfen in ihrem Tal bei.",
			text = [=[Nun sind {link:dwarves}Zwerge{/link} in {link:stranglethorn-vale}das Tal{/link} gekommen, das die {link:frostwolf-clan}Frostwölfe{/link} in ihren dunkelsten Jahren beschützte. Der Clan, der dem Kriegshäuptling teuer ist, wird angegriffen, und der Ruf ist durch die ganze {link:horde}Horde{/link} gegangen. Krieger werden nördlich von {link:tarren-mill}Tarrens Mühle{/link} zu Kriegsmeister Laggrond geschickt, der sie am Eingang des Tals prüft, bevor sie kämpfen.]=],
		},
	},
	mentions = {
		{ text = "Zur Verteidigung der Frostwolf" },
		{ text = "Die Schlacht von {link:alterac-mountains}Alterac{/link}" },
		{ text = "Bewährungsprobe" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "sein Schüler und Kriegshäuptling" },
		{ id = "vanndar-stormpike", name = "Vanndar Stormpike", note = "sein Feind" },
		{ id = "voggah-deathgrip", name = "Voggah Deathgrip", note = "schickt ihm Krieger zu Hilfe" },
	},
})

Translate("deDE", "crushridge-ogres", {
	title = "Crushridge-Oger",
	aliases = { "Crushridge", "Crushridge-Oger", "Crushridge-Clan" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Crushridge sind eine Kriegerschar von {link:ogres}Ogern{/link}, die die Ruinen der alten {link:capital-city}Hauptstadt{/link} Alteracs für sich genommen haben. Rohlinge, Schläger, Kriegstreiber, Vollstrecker und Magier füllen die Straßen, durch die einst die Könige Alteracs ritten. Sie haben in den Hügeln nahe der Stadt einen großen Hügelbau gegraben und einen zweiten tiefer in den Bergen, und ihre Patrouillen bewachen die Wegkreuzung in Richtung {link:tarren-mill}Tarrens Mühle{/link}.]=],
		},
		{
			title = "Die Krone des Willens",
			text = [=[Die Crushridge kamen nicht aus eigenem Willen nach {link:alterac-mountains}Alterac{/link}. Ihr Kriegsherr {link:mug-thol}Mug'thol{/link} war an den Dienst von {link:sylvanas-windrunner}Sylvanas Windrunner{/link} gebunden, und sie schickte seine Kriegerschar in die Berge, um ein Relikt namens Krone des Willens zu bergen. Mug'thol fand die Krone und setzte sie auf. Sie befreite ihn aus dem Griff der Dunklen Fürstin, und seine {link:ogres}Oger{/link} folgten ihm als ihre eigenen Herren in die Ruinen. Drei Leutnants, Targ, Muckrake und Glommus, stehen an seiner Seite, und der Ogermagier {link:grel-borg-the-miser}Grel'borg{/link} durchsucht die Stadt nach Schätzen.]=],
		},
		{
			title = "Feinde auf allen Seiten",
			text = [=[Die Verlassenen von {link:tarren-mill}Tarrens Mühle{/link} wollen die Krone und mit ihr die Köpfe von {link:mug-thol}Mug'thol{/link} und seinen Leutnants. Die Soldaten von {link:southshore}Southshore{/link} fürchten, dass die {link:ogres}Oger{/link} in die Vorberge herabkommen werden, und ihr Marschall zahlt ein Kopfgeld für jeden erschlagenen Oger. Die Oger haben auch gegen das {link:syndicate}Syndikat{/link} um die Ruinen des Königreichs gekämpft, das beide beanspruchen.]=],
		},
	},
})

Translate("deDE", "argus-wake", {
	title = "Argus Wake",
	aliases = { "der Argus Wake" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Argus Wake ist ein geheimer Orden, der sich in {link:alterac-mountains}Alterac{/link} zum Verbündeten des {link:syndicate}Syndikats{/link} gemacht hat. Seine Schattenmagier warten im {link:the-uplands}Oberland{/link}, und sein Hierophant, der {link:orcs}Orc{/link} {link:nagaz}Nagaz{/link}, steht neben {link:lord-aliden-perenolde}Lord Aliden Perenolde{/link}. Die Adligen Alteracs glauben, mächtige Freunde gefunden zu haben. Sie irren sich.]=],
		},
		{
			title = "Der Brief",
			text = [=[Die Wahrheit kam durch einen Brief ans Licht, der in einem Lager des Syndikats gefunden wurde. Er war in einer so seltenen Chiffre geschrieben, dass nicht einmal {link:lore-keeper-of-norgannon}der Wissenshüter{/link} von {link:southshore}Southshore{/link} ihn lesen konnte, und er musste zu einem Prospektor in {link:ironforge}Ironforge{/link} gebracht werden. {link:nagaz}Nagaz{/link} hatte ihn an das Haupt des Wake geschrieben, den er als seinen Herrn ansprach, eingesetzt von einem Rat. Das {link:syndicate}Syndikat{/link}, schrieb er, werde mit der Führung des Wake {link:alterac-mountains}Alterac{/link} zurückgewinnen und dann {link:stromgarde-keep}Stromgarde{/link} nehmen. Mit einer eigenen Nation und einer eigenen Machtbasis werde der Wake dann den Weg für das bereiten, was er das Dritte Heer nannte. Er unterzeichnete im Namen von {link:sargeras}Sargeras{/link}.]=],
		},
		{
			title = "Was unbekannt bleibt",
			text = [=[{link:magistrate-henry-maleb}Magistrat Maleb{/link} von {link:southshore}Southshore{/link} schickte Jäger hinter {link:nagaz}Nagaz{/link} und seinen Magiern her. Dennoch weiß der Magistrat, dass Nagaz nur ein Diener war. Wer den Argus Wake führt und wie weit seine Wurzeln reichen, kann in Southshore niemand sagen.]=],
		},
	},
})

Translate("deDE", "stormpike-guard", {
	title = "Stormpikegarde",
	aliases = { "Stormpike-Expedition", "Stormpike" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Stormpikegarde ist eine Expedition von {link:dwarves}Zwergen{/link} des Stormpike-Clans im {link:alterac-valley}Alteractal{/link}, unter dem Befehl von General {link:vanndar-stormpike}Vanndar Stormpike{/link}. Von ihrer Festung Dun Baldar im Norden des Tals aus durchsuchen sie das Land nach Erz und nach Relikten ihrer Vergangenheit. {link:humans}Menschen{/link}, {link:gnomes}Gnome{/link} und {link:night-elves}Nachtelfen{/link} der {link:alliance}Allianz{/link} kämpfen in ihren Reihen.]=],
		},
		{
			title = "Das Gebot",
			text = [=[Die Expedition ist zu einem Krieg geworden. König {link:magni-bronzebeard}Magni Bronzebeard{/link} hat die Einnahme der Täler Alteracs zur Pflicht des {link:kingdom-of-ironforge}Königreichs Ironforge{/link} erklärt, und die Stormpike kämpfen darum, sie gegen die Winterax-{link:trolls}Trolle{/link} und die {link:orcs}Orcs{/link} des {link:frostwolf-clan}Frostwolfklans{/link} zu erobern. Die Gelehrten der {link:explorers-league}Forscherliga{/link} marschieren mit ihnen, sicher, dass {link:stranglethorn-vale}das Tal{/link} Artefakte birgt, die den Kampf wert sind. Die Orcs nennen sie Eindringlinge. Die {link:dwarves}Zwerge{/link} nennen das Tal von Rechts wegen das ihre.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Vor dem Tunnel ins Tal empfangen Offiziere der Stormpike die Soldaten der {link:alliance}Allianz{/link}, prüfen sie in den Höhlen des Tals und geben ihnen die Abzeichen der Garde. Die Widder der {link:dwarves}Zwerge{/link}, gezüchtet auf der {link:amberstill-ranch}Amberstill-Ranch{/link} in {link:dun-morogh}Dun Morogh{/link}, ziehen nach Norden, um die Expedition zu verstärken.]=],
		},
	},
})

Translate("deDE", "frostwolf-clan", {
	title = "Frostwolfklan",
	aliases = { "Frostwölfe", "Frostwolf-Clan", "Frostwolf-Orcs" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Frostwolfklan ist ein Orcclan, der seine Heimat im {link:alterac-valley}Alteractal{/link} hat. Er ist der Clan von {link:thrall}Thrall{/link}s Vater, und der Kriegshäuptling hält ihn in Ehren. Seine Krieger reiten die großen weißen Wölfe der Berge, und sein ältester Schamane, {link:drek-thar}Drek'Thar{/link}, führt ihn von Burg Frostwolf im Süden des Tals aus.]=],
		},
		{
			title = "Die Verbannung",
			text = [=[Auf Draenor waren die Frostwölfe ein stolzer Clan unter ihrem Häuptling Durotan. Als die {link:orcs}Orcs{/link} nach {link:azeroth}Azeroth{/link} kamen, sprach Durotan sich gegen {link:gul-dan}Gul'dan{/link} und den dunklen Pfad aus, den die {link:horde}Horde{/link} eingeschlagen hatte. Dafür wurde sein Clan ins {link:alterac-mountains}Alteracgebirge{/link} verbannt. Durotan und seine Gefährtin verließen {link:stranglethorn-vale}das Tal{/link} später, und beide wurden von Handlangern Gul'dans ermordet. Ihr kleiner Sohn wurde von einem menschlichen Offizier gefunden, der ihn in {link:durnholde-keep}Durnholde{/link} als Sklaven aufzog. Die Frostwölfe ertrugen die Kälte und die langen Jahre allein, und fern von der {link:fel-magic}Teufelsmagie{/link} der Horde erlernten ihre Schamanen die Wege der Geister neu.]=],
		},
		{
			title = "Die Rückkehr des Sohnes",
			text = [=[Jahre später kam ein junger {link:orcs}Orc{/link} in ihr Lager, ein Entlaufener aus {link:durnholde-keep}Durnholde{/link}. Er war Durotans Sohn. {link:drek-thar}Drek'Thar{/link} lehrte ihn die Wege des Schamanen, und aus dem Tal zog {link:thrall}Thrall{/link} aus, um die Orcs der Lager zu befreien und eine neue {link:horde}Horde{/link} aufzubauen.]=],
